 static final GenericContainer<?> PG=IsolatedContainers.postgres("single-authority"),REDIS=IsolatedContainers.redis("single-authority");static final UUID CLUSTER=UUID.randomUUID(),INSTANCE=UUID.randomUUID();static EventFoundationTestSupport.Database db;static Path directory,tokenFile;static String originalNode;static long user;
