  var waiting=http.send(HttpRequest.newBuilder(URI.create(callbackUrl)).header("X-Deployment-Token",callbackToken).GET().build(),HttpResponse.BodyHandlers.ofString());assertEquals(200,waiting.statusCode(),waiting.body());assertFalse(json.readTree(waiting.body()).path("authorized").asBoolean());
