  var callbackCannotReadNode=http.send(HttpRequest.newBuilder(URI.create("http://127.0.0.1:"+port+"/internal/cluster/v1/probe")).header("X-Deployment-Token",callbackToken).GET().build(),HttpResponse.BodyHandlers.ofString());assertEquals(401,callbackCannotReadNode.statusCode());
  var callbackCannotReadAdmin=http.send(HttpRequest.newBuilder(URI.create("http://127.0.0.1:"+port+"/admin/control/v1/cluster/deployment-fences")).header("X-Deployment-Token",callbackToken).GET().build(),HttpResponse.BodyHandlers.ofString());assertEquals(401,callbackCannotReadAdmin.statusCode());
  var malformedProof=http.send(HttpRequest.newBuilder(URI.create(callbackUrl.replace("?manifest="+"a".repeat(64),""))).header("X-Deployment-Token",callbackToken).GET().build(),HttpResponse.BodyHandlers.ofString());assertEquals(400,malformedProof.statusCode(),malformedProof.body());
  var blockedReload=http.send(HttpRequest.newBuilder(URI.create("http://127.0.0.1:"+port+"/admin/control/v1/cluster/profiles/reload")).header("eatwhat-test-token",token.startsWith("Bearer ")?token:"Bearer "+token).POST(HttpRequest.BodyPublishers.noBody()).build(),HttpResponse.BodyHandlers.ofString());assertEquals(409,blockedReload.statusCode());assertTrue(blockedReload.body().contains("DEPLOYMENT_RECONCILIATION_REQUIRED"));deploymentFence.finish(release,"a".repeat(64),"FAILED",false);
  var finalProof=http.send(HttpRequest.newBuilder(URI.create(callbackUrl)).header("X-Deployment-Token",callbackToken).GET().build(),HttpResponse.BodyHandlers.ofString());assertEquals(200,finalProof.statusCode());assertFalse(json.readTree(finalProof.body()).path("authorized").asBoolean());assertEquals("FAILED",json.readTree(finalProof.body()).path("state").asText());
  var runtimeCapabilities=http.send(HttpRequest.newBuilder(URI.create("http://127.0.0.1:"+port+"/admin/control/v1/cluster/capabilities")).header("eatwhat-test-token",token.startsWith("Bearer ")?token:"Bearer "+token).GET().build(),HttpResponse.BodyHandlers.ofString());assertEquals(200,runtimeCapabilities.statusCode(),runtimeCapabilities.body());assertEquals("UNAVAILABLE",json.readTree(runtimeCapabilities.body()).path("controllerRuntimeArtifact").path("status").asText());assertFalse(runtimeCapabilities.body().contains(directory.toString()));
  var docker=PG.getDockerClient();docker.pauseContainerCmd(PG.getContainerId()).exec();
  try{
   long began=System.nanoTime();var diagnostic=http.send(HttpRequest.newBuilder(URI.create("http://127.0.0.1:"+port+"/internal/cluster/v1/health-check")).header("X-Control-Node-Token",Files.readString(tokenFile)).header("Content-Type","application/json").POST(HttpRequest.BodyPublishers.ofString("{\"requestId\":\""+UUID.randomUUID()+"\"}")).build(),HttpResponse.BodyHandlers.ofString());assertEquals(200,diagnostic.statusCode(),diagnostic.body());assertTrue(java.time.Duration.ofNanos(System.nanoTime()-began).toSeconds()<3);
   long end=System.nanoTime()+java.util.concurrent.TimeUnit.SECONDS.toNanos(10);boolean timedOut=false;while(System.nanoTime()<end){var diagnosticRead=http.send(HttpRequest.newBuilder(URI.create("http://127.0.0.1:"+port+"/internal/cluster/v1/health")).header("X-Control-Node-Token",Files.readString(tokenFile)).GET().build(),HttpResponse.BodyHandlers.ofString());assertEquals(200,diagnosticRead.statusCode());var body=json.readTree(diagnosticRead.body());String state=body.path("control").path("healthChecks").path("database").path("status").asText();if(Set.of("FAIL","UNKNOWN").contains(state)){timedOut=true;assertNotEquals("READY",body.path("control").path("readiness").asText());assertEquals("CONFIGURATION_ONLY",body.path("identityProof").asText());break;}Thread.sleep(100);}assertTrue(timedOut,"Database outage must remain diagnosable without a database-backed identity claim");
  }finally{docker.unpauseContainerCmd(PG.getContainerId()).exec();}
